function save(){localStorage.setItem(KEY,JSON.stringify(S))}
function applyTheme(){document.documentElement.classList.remove("dark");document.documentElement.style.setProperty("--primary",S.cms.primary);document.documentElement.style.setProperty("--accent",S.cms.accent);document.documentElement.style.setProperty("--beige",S.cms.beige);document.documentElement.style.setProperty("--cream",S.cms.cream);document.documentElement.style.setProperty("--dark",S.cms.dark);document.documentElement.style.setProperty("--green",S.cms.green);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',S.cms.pwa?.themeColor||S.cms.primary)}
function logo(){return S.cms.logo||"assets/nona-me-logo.png"}function nav(){let n=[["sales","💰"],["menu","☕"],["expenses","🧾"],["cash","💵"],["deposit","🏦"],["stock","📦"],["report","📊"],["reports","📆"],["history","🗂️"]].filter(([k])=>S.cms.nav?.[k]!==false);if(S.role==="admin")n.push(["admin","⚙️"]);return n}
function langSwitch(){return `<button class="btn" id="langBtn">${S.lang==="kh"?"English":"ខ្មែរ"}</button>`}
function render(){applyTheme();if(!S.user){document.getElementById("app").innerHTML=loginView();bindLogin();return}document.getElementById("app").innerHTML=appView();bindGlobal();renderPage()}
function loginView(){return `<div class="login-screen"><div class="login-card panel"><img class="login-logo" src="${logo()}"><h2>${esc(S.cms.shopName)}</h2><p class="muted">${esc(S.cms.tagline)}</p><div class="field"><label>${L("username")}</label><input id="loginUser" autocomplete="username"></div><div class="field" style="margin-top:9px"><label>${L("password")}</label><input id="loginPass" type="password" autocomplete="current-password"></div><label style="display:flex;gap:8px;align-items:center;margin:10px 0;font-weight:700"><input id="remember" type="checkbox" style="width:auto" ${S.remember?"checked":""}>${L("remember")}</label><button id="doLogin" class="btn btn-primary" style="width:100%;padding:12px">${L("login")}</button><div class="small muted" style="margin-top:10px">Staff: staff01 / 1234 · Admin: admin / admin</div><div class="login-actions" style="margin-top:10px">${langSwitch()}</div></div></div>`}
function appView(){let top=nav().map(([k,i])=>`<button class="tab ${S.page===k?"active":""}" data-page="${k}">${i} ${L(k)}</button>`).join("");let b=(S.role==="admin"?[["sales","💰"],["menu","☕"],["report","📊"],["stock","📦"],["admin","⚙️"]]:[["sales","💰"],["menu","☕"],["report","📊"],["stock","📦"],["cash","💵"]]).map(([k,i])=>`<button class="${S.page===k?"active":""}" data-page="${k}">${i}<br>${L(k)}</button>`).join("");return `<header class="topbar"><div class="brand"><img src="${logo()}"><div><div class="brand-title">${esc(S.cms.shopName)}</div><div class="brand-sub">Nona-me Sales</div></div></div><div class="top-actions">${langSwitch()}<button class="btn" id="switchUser">${L("switchUser")}</button><button class="btn" id="logout">${L("logout")}</button></div></header><main class="wrap"><nav class="tabs">${top}</nav>${S.cms.showAnnouncement&&S.cms.announcement?`<div class="site-announcement">📢 ${esc(S.cms.announcement)}</div>`:""}<div id="page"></div></main><nav class="bottom-nav">${b}</nav><div id="modalRoot"></div>`}
function bindLogin(){$("langBtn").onclick=()=>{S.lang=S.lang==="kh"?"en":"kh";save();render()};$("doLogin").onclick=()=>{let u=$("loginUser").value.trim(),p=$("loginPass").value,user=S.users.find(x=>x.username===u&&x.password===p&&x.active!==false);if(!user)return alert(L("required"));S.user={id:user.id,name:user.name,username:user.username,role:user.role};S.role=user.role;S.remember=$("remember").checked;save();render()}}
function bindGlobal(){document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>{if(b.dataset.page==="reports"&&S.role!=="admin")return;S.page=b.dataset.page;save();renderPage()});$("langBtn").onclick=()=>{S.lang=S.lang==="kh"?"en":"kh";save();render()};$("switchUser").onclick=()=>{S.user=null;S.role=null;save();render()};$("logout").onclick=()=>{S.user=null;S.role=null;save();render()}}
function renderPage(){
  let p=$("page");
  if(!p)return;
  try{
    if(S.page==="sales"||S.page==="menu")p.innerHTML=renderSales(S.page==="menu"),bindSales();
    else if(S.page==="expenses")p.innerHTML=renderExpenses(),bindExpenses();
    else if(S.page==="cash")p.innerHTML=renderCash(),bindCash();
    else if(S.page==="deposit")p.innerHTML=renderDeposit(),bindDeposit();
    else if(S.page==="stock")p.innerHTML=renderStock(),bindStock();
    else if(S.page==="report")p.innerHTML=renderReport(),bindReport();
    else if(S.page==="reports")p.innerHTML=renderPeriod(),bindPeriod();
    else if(S.page==="history")p.innerHTML=renderHistory();
    else if(S.page==="admin"){if(S.role!=="admin"){S.page="sales";save();renderPage();return}p.innerHTML=renderAdmin();bindAdmin();}
  }catch(err){
    console.error(err);
    p.innerHTML=`<section class="panel"><h2>${S.lang==='kh'?'គ្រប់គ្រងមិនអាចបើកបាន':'Admin could not load'}</h2><p class="muted">${esc(err?.message||'Unknown error')}</p><button class="btn btn-primary" id="adminRecover">${S.lang==='kh'?'ផ្ទុកឡើងវិញ':'Reload Admin'}</button></section>`;
    $("adminRecover")?.addEventListener('click',()=>{S.page='admin';save();renderPage()});
  }
}
function cats(){return [L("all"),...new Set(S.products.filter(p=>p.active!==false).map(p=>p.category))]}
function renderSales(menuOnly=false){let q=S.ui.search||"",cat=S.ui.category,list=S.products.filter(p=>p.active!==false&&(cat===L("all")||cat===p.category)&&((p.en||"").toLowerCase().includes(q.toLowerCase())||(p.kh||"").includes(q)));let cards=list.map(p=>`<button class="product-card" data-add="${p.id}"><img class="product-image" src="${esc(p.image||"assets/nona-me-logo.png")}"><div class="product-name">${esc(p[S.lang])}</div><div class="product-alt">${esc(S.lang==="kh"?p.en:p.kh)}</div><div class="price">${mKHR(p.price)}</div><div class="price-usd ${S.cms.showPriceUSD===false?"hidden":""}">$${(p.price/(S.settings.rate||4000)).toFixed(2)}</div></button>`).join("");if(menuOnly)return `<div class="page-head"><div><h1>☕ ${L("menu")}</h1></div><div class="action-row"><select id="cat">${cats().map(c=>`<option ${c===cat?"selected":""}>${esc(c)}</option>`).join("")}</select><button class="btn" id="viewMode">${S.ui.menuView==="grid"?L("list"):L("grid")}</button></div></div><section class="panel menu-panel"><input id="menuSearch" placeholder="${L("search")}" value="${esc(q)}"><div class="menu-scroll"><div id="products" class="product-grid ${S.ui.menuView==="list"?"list-view":""}">${cards||`<div class="empty">${L("noRecords")}</div>`}</div></div></section>`;let total=cartTotal();let promoOpts=S.promotions.filter(p=>p.active).map(p=>`<option value="${p.id}">${esc(p[S.lang])} · ${p.qty} → ${mKHR(p.price)}</option>`).join("");return `<div class="page-head"><div><h1>${L("today")}</h1><div class="muted">${esc(S.user.name)}</div></div><div class="action-row"><select id="cat">${cats().map(c=>`<option ${c===cat?"selected":""}>${esc(c)}</option>`).join("")}</select><button class="btn" id="viewMode">${S.ui.menuView==="grid"?L("list"):L("grid")}</button></div></div>${S.cms.showStats!==false?`<div class="stats"><div class="stat"><small>KHR</small><strong>${mKHR(daySales("KHR"))}</strong></div><div class="stat"><small>USD</small><strong>${mUSD(daySales("USD"))}</strong></div><div class="stat"><small>${L("cups")}</small><strong>${dayCups()}</strong></div><div class="stat"><small>${L("total")}</small><strong>${S.sales.filter(x=>x.date===today()).length}</strong></div></div>`:""}<div class="sales-grid"><section class="panel menu-panel"><div class="row-between"><h2>${L("menu")}</h2><input id="menuSearch" class="search" style="max-width:220px" placeholder="${L("search")}" value="${esc(q)}"></div><div class="menu-scroll"><div id="products" class="product-grid ${S.ui.menuView==="list"?"list-view":""}">${cards||`<div class="empty">${L("noRecords")}</div>`}</div></div></section><section class="panel"><h2>${L("current")}</h2><div class="cart-list">${S.ui.cart.map(i=>{let p=S.products.find(x=>x.id===i.id);return `<div class="cart-item"><div><b>${esc(p?.[S.lang]||i.id)}</b><div class="small muted">${mKHR(i.price)} × ${i.qty}</div></div><div class="qty"><button data-q="-1" data-id="${i.id}">−</button><b>${i.qty}</b><button data-q="1" data-id="${i.id}">+</button></div></div>`}).join("")||`<div class="empty">${L("noRecords")}</div>`}</div><div class="field"><label>${L("promotion")}</label><select id="promo"><option value="">${L("none")}</option>${promoOpts}</select></div><div class="form-grid" style="margin-top:9px"><div class="field"><label>${L("currency")}</label><select id="currency"><option value="KHR">KHR</option><option value="USD">USD</option></select></div><div class="field"><label>${L("rate")}</label><input id="rate" type="number" value="${S.settings.rate}"></div></div><div class="field" style="margin-top:9px"><label>${L("payment")}</label><select id="payment"><option>Cash</option><option>ABA</option><option>Other</option></select></div><div class="total"><span>${L("total")}</span><b>${total.display}</b></div><div class="action-row"><button class="btn btn-primary" id="saveSale">${L("save")}</button><button class="btn" id="savePrint">${L("savePrint")}</button></div></section></div>`}
function bindSales(){
  let c=$("cat");
  if(c)c.onchange=()=>{S.ui.category=c.value;save();renderPage()};
  let s=$("menuSearch");
  if(s)s.oninput=()=>{S.ui.search=s.value;renderPage()};
  if($("viewMode"))$("viewMode").onclick=()=>{S.ui.menuView=S.ui.menuView==="grid"?"list":"grid";save();renderPage()};
  document.querySelectorAll("[data-add]").forEach(b=>b.onclick=()=>{addCart(b.dataset.add);renderPage()});
  document.querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>{changeCart(b.dataset.id,+b.dataset.q);renderPage()});
  if($("currency"))$("currency").onchange=e=>{S.ui.currency=e.target.value;save();renderPage()};
  if($("payment")){ $("payment").value=S.ui.payment; $("payment").onchange=e=>{S.ui.payment=e.target.value;save()} }
  if($("rate"))$("rate").onchange=e=>{S.settings.rate=+e.target.value||4000;save();renderPage()};
  if($("promo")){ $("promo").onchange=()=>renderPage(); $("promo").addEventListener('input',()=>renderPage()); }
  if($("saveSale"))$("saveSale").onclick=()=>saveSale(false);
  if($("savePrint"))$("savePrint").onclick=()=>saveSale(true);
}
function addCart(id){let p=S.products.find(x=>x.id===id),x=S.ui.cart.find(x=>x.id===id);if(x)x.qty++;else S.ui.cart.push({id,qty:1,price:p.price});save()}
function changeCart(id,d){let x=S.ui.cart.find(x=>x.id===id);if(!x)return;x.qty+=d;if(x.qty<=0)S.ui.cart=S.ui.cart.filter(i=>i.id!==id);save()}
function cartTotal(){let normal=S.ui.cart.reduce((a,i)=>a+i.qty*i.price,0),promo=$("promo")?.value?S.promotions.find(x=>x.id===$("promo").value&&x.active):null,q=S.ui.cart.reduce((a,i)=>a+i.qty,0);if(promo&&q>=promo.qty){let sets=Math.floor(q/promo.qty),avg=q?normal/q:0;normal-=sets*Math.max(0,promo.qty*avg-promo.price)}return {raw:normal,display:S.ui.currency==="KHR"?mKHR(normal):mUSD(normal/S.settings.rate)}}
function saveSale(print){if(!S.ui.cart.length)return alert(L("required"));let d=dt(),t=cartTotal().raw,s={id:uid("s"),date:d.date,time:d.time,user:S.user.name,role:S.role,currency:S.ui.currency,payment:S.ui.payment,rate:+$("rate").value||S.settings.rate,amount:t,cups:S.ui.cart.reduce((a,x)=>a+x.qty,0),items:S.ui.cart.map(x=>({...x})),promotionId:$("promo")?.value||""};S.sales.push(s);S.ui.cart=[];save();renderPage();if(print)printReceipt(s);alert(L("saved"))}
function daySales(cur){return S.sales.filter(x=>x.date===today()&&x.currency===cur).reduce((a,x)=>a+x.amount,0)}function dayCups(){return S.sales.filter(x=>x.date===today()).reduce((a,x)=>a+x.cups,0)}
function renderExpenses(){return `<div class="page-head"><h1>${L("expenses")}</h1></div><div class="two-col"><section class="panel"><div class="field"><label>${L("expenseOn")}</label><input id="exDesc"></div><div class="form-grid" style="margin-top:9px"><div class="field"><label>${L("amount")}</label><input id="exAmount" type="number"></div><div class="field"><label>${L("currency")}</label><select id="exCur"><option>KHR</option><option>USD</option></select></div></div><div class="field" style="margin-top:9px"><label>${L("payment")}</label><select id="exPay"><option>Cash</option><option>ABA</option><option>Other</option></select></div><div class="field" style="margin-top:9px"><label>${L("note")}</label><textarea id="exNote"></textarea></div><button class="btn btn-primary" id="saveEx" style="margin-top:9px">${L("save")}</button></section><section class="panel"><h2>${L("history")}</h2>${S.expenses.slice().reverse().slice(0,30).map(x=>`<div class="user-row"><div><b>${esc(x.desc)}</b><div class="small muted">${x.date} ${x.time} · ${esc(x.user)}</div></div><b>${x.currency==="KHR"?mKHR(x.amount):mUSD(x.amount)}</b></div>`).join("")||`<div class="empty">${L("noRecords")}</div>`}</section></div>`}
function bindExpenses(){$("saveEx").onclick=()=>{let d=$("exDesc").value.trim(),a=+$("exAmount").value||0;if(!d||a<=0)return alert(L("required"));let t=dt();S.expenses.push({id:uid("e"),date:t.date,time:t.time,user:S.user.name,desc:d,amount:a,currency:$("exCur").value,method:$("exPay").value,note:$("exNote").value});save();renderPage()}}
function cashExpected(cur,before=false){let end=before?today():today();let sales=S.sales.filter(x=>x.currency===cur&&x.payment==="Cash"&&x.date<=end).reduce((a,x)=>a+x.amount,0),exp=S.expenses.filter(x=>x.currency===cur&&x.method==="Cash"&&x.date<=end).reduce((a,x)=>a+x.amount,0),dep=S.deposits.filter(x=>x.currency===cur&&x.date<=end).reduce((a,x)=>a+x.amount,0);return sales-exp-dep}
function renderCash(){let k=cashExpected("KHR"),u=cashExpected("USD");return `<div class="page-head"><h1>${L("cash")}</h1></div><div class="stats"><div class="stat"><small>KHR</small><strong>${mKHR(k)}</strong></div><div class="stat"><small>USD</small><strong>${mUSD(u)}</strong></div></div><section class="panel"><h2>${L("actual")}</h2><div class="form-grid"><div class="field"><label>KHR</label><input id="ak" type="number"></div><div class="field"><label>USD</label><input id="au" type="number" step="0.01"></div></div><button class="btn btn-primary" id="saveCount" style="margin-top:9px">${L("save")}</button>${S.cashCounts.slice().reverse().slice(0,10).map(x=>`<div class="user-row"><div><b>${x.date}</b><div class="small muted">${esc(x.user)} · ${x.time}</div></div><span>${mKHR(x.khr)} · ${mUSD(x.usd)}</span></div>`).join("")}</section>`}
function bindCash(){$("saveCount").onclick=()=>{let t=dt(),k=+$("ak").value||0,u=+$("au").value||0;S.cashCounts.push({id:uid("c"),date:t.date,time:t.time,user:S.user.name,khr:k,usd:u,expectedKhr:cashExpected("KHR"),expectedUsd:cashExpected("USD")});save();renderPage()}}
function renderDeposit(){return `<div class="page-head"><h1>${L("deposit")}</h1></div><section class="panel" style="max-width:760px"><div class="form-grid"><div class="field"><label>${L("amount")}</label><input id="da" type="number"></div><div class="field"><label>${L("currency")}</label><select id="dc"><option>KHR</option><option>USD</option></select></div><div class="field"><label>Bank</label><input id="db"></div><div class="field"><label>${L("note")}</label><input id="dn"></div></div><button class="btn btn-primary" id="saveDep" style="margin-top:9px">${L("save")}</button></section>`}
function bindDeposit(){$("saveDep").onclick=()=>{let a=+$("da").value||0;if(a<=0)return alert(L("required"));let t=dt();S.deposits.push({id:uid("d"),date:t.date,time:t.time,user:S.user.name,amount:a,currency:$("dc").value,bank:$("db").value,note:$("dn").value});save();renderPage()}}
function squareImage(file,done){
  if(!file){done('');return}
  const url=URL.createObjectURL(file),img=new Image();
  img.onload=()=>{
    try{
      const side=Math.min(img.naturalWidth||img.width,img.naturalHeight||img.height);
      const sx=((img.naturalWidth||img.width)-side)/2, sy=((img.naturalHeight||img.height)-side)/2;
      const canvas=document.createElement('canvas');
      const size=Math.min(900,Math.max(320,side)); canvas.width=size; canvas.height=size;
      const ctx=canvas.getContext('2d'); ctx.drawImage(img,sx,sy,side,side,0,0,size,size);
      done(canvas.toDataURL('image/jpeg',.88));
    }finally{URL.revokeObjectURL(url)}
  };
  img.onerror=()=>{URL.revokeObjectURL(url);done('')};
  img.src=url;
}
function bindPhotoPicker(inputId,previewId,statusId,uploadId,retakeId,removeId){
  const input=$(inputId), preview=$(previewId), status=$(statusId), upload=$(uploadId), retake=$(retakeId), remove=$(removeId);
  if(!input)return;
  const reset=()=>{input.value='';preview.src='assets/nona-me-logo.png';preview.dataset.image='';status.textContent=L('photoPreview');upload.classList.remove('hidden');retake.classList.add('hidden');remove.classList.add('hidden')};
  const pick=()=>{
    const f=input.files&&input.files[0]; if(!f)return;
    squareImage(f,img=>{if(!img)return;preview.src=img;preview.dataset.image=img;status.textContent='1:1';upload.classList.add('hidden');retake.classList.remove('hidden');remove.classList.remove('hidden')});
  };
  input.onchange=pick;
  upload.onclick=()=>input.click();
  retake.onclick=()=>input.click();
  remove.onclick=reset;
  return {reset};
}
function renderStock(){return `<div class="page-head"><div><h1>${L("stock")}</h1></div></div><div class="two-col"><section class="panel"><div class="form-grid"><div class="field"><label>${L("item")}</label><input id="sn"></div><div class="field"><label>${L("quantity")}</label><input id="sq" type="number" min="0"></div><div class="field"><label>${L("unit")}</label><input id="su"></div><div class="field"><label>${L("minimum")}</label><input id="sm" type="number" min="0" value="0"></div></div><div class="stock-photo-box"><div class="stock-photo-top"><div><b>${L("image")}</b><div class="small muted">1:1</div></div><span id="siStatus" class="small muted">${L("photoPreview")}</span></div><div class="stock-photo-preview-wrap"><img id="siPreview" class="stock-photo-preview" src="assets/nona-me-logo.png"></div><div class="photo-actions"><button class="btn btn-primary" id="siUpload" type="button">🖼️ ${L("uploadPhoto")}</button><button class="btn" id="siCamera" type="button">📷 ${L("takePhoto")}</button><button class="btn hidden" id="siRetake" type="button">🔄 ${L("retakePhoto")}</button><button class="btn btn-danger hidden" id="siRemove" type="button">✕ ${L("removePhoto")}</button></div><input id="siUploadInput" class="hidden" type="file" accept="image/*"><input id="si" class="hidden" type="file" accept="image/*" capture="environment"></div><div class="field" style="margin-top:9px"><label>${L("note")}</label><textarea id="st"></textarea></div><button class="btn btn-primary" id="saveStock" style="margin-top:9px">${L("addStock")}</button></section><section class="panel">${S.stock.slice().reverse().map(x=>`<div class="stock-row"><img class="thumb" src="${esc(x.image||"assets/nona-me-logo.png")}"><div><b>${esc(x.name)}</b><div class="small muted">${x.qty} ${esc(x.unit||"")} ${x.qty<=x.min?"· ⚠️ "+L("lowStock"):""}</div><div class="small muted">${esc(x.note||"")}</div></div><span class="badge ${x.qty<=x.min?"red":"green"}">${x.qty<=x.min?L("lowStock"):L("active")}</span></div>`).join("")||`<div class="empty">${L("noRecords")}</div>`}</section></div>`}
function bindStock(){
  const uploadInput=$("siUploadInput"), cameraInput=$("si"), preview=$("siPreview"), status=$("siStatus"), uploadBtn=$("siUpload"), cameraBtn=$("siCamera"), retake=$("siRetake"), remove=$("siRemove");
  let imageData="";
  const applyImage=(file)=>squareImage(file,img=>{if(!img)return;imageData=img;preview.src=img;status.textContent="1:1";uploadBtn.classList.add("hidden");cameraBtn.classList.add("hidden");retake.classList.remove("hidden");remove.classList.remove("hidden")});
  uploadBtn.onclick=()=>uploadInput.click();
  cameraBtn.onclick=()=>cameraInput.click();
  retake.onclick=()=>cameraInput.click();
  remove.onclick=()=>{imageData="";uploadInput.value="";cameraInput.value="";preview.src="assets/nona-me-logo.png";status.textContent=L("photoPreview");uploadBtn.classList.remove("hidden");cameraBtn.classList.remove("hidden");retake.classList.add("hidden");remove.classList.add("hidden")};
  uploadInput.onchange=()=>uploadInput.files[0]&&applyImage(uploadInput.files[0]);
  cameraInput.onchange=()=>cameraInput.files[0]&&applyImage(cameraInput.files[0]);
  $("saveStock").onclick=()=>{let n=$("sn").value.trim(),q=+$(("sq")).value||0;if(!n||q<=0)return alert(L("required"));S.stock.push({id:uid("st"),name:n,qty:q,unit:$("su").value.trim(),min:+$("sm").value||0,image:imageData,note:$("st").value.trim(),user:S.user.name,date:today()});save();renderPage()}
}
function reportData(){
  const date=today();
  const sales=S.sales.filter(x=>x.date===date);
  const expenses=S.expenses.filter(x=>x.date===date);
  const deposits=S.deposits.filter(x=>x.date===date);
  const sk=sales.filter(x=>x.currency==="KHR").reduce((a,x)=>a+(+x.amount||0),0);
  const su=sales.filter(x=>x.currency==="USD").reduce((a,x)=>a+(+x.amount||0),0);
  const ek=expenses.filter(x=>x.currency==="KHR").reduce((a,x)=>a+(+x.amount||0),0);
  const eu=expenses.filter(x=>x.currency==="USD").reduce((a,x)=>a+(+x.amount||0),0);
  const dk=deposits.filter(x=>x.currency==="KHR").reduce((a,x)=>a+(+x.amount||0),0);
  const du=deposits.filter(x=>x.currency==="USD").reduce((a,x)=>a+(+x.amount||0),0);
  const csk=sales.filter(x=>x.payment==="Cash"&&x.currency==="KHR").reduce((a,x)=>a+(+x.amount||0),0);
  const csu=sales.filter(x=>x.payment==="Cash"&&x.currency==="USD").reduce((a,x)=>a+(+x.amount||0),0);
  const cek=expenses.filter(x=>x.method==="Cash"&&x.currency==="KHR").reduce((a,x)=>a+(+x.amount||0),0);
  const ceu=expenses.filter(x=>x.method==="Cash"&&x.currency==="USD").reduce((a,x)=>a+(+x.amount||0),0);
  const expectedKhr=cashExpected("KHR"), expectedUsd=cashExpected("USD");
  const previousKhr=expectedKhr-csk+cek+dk;
  const previousUsd=expectedUsd-csu+ceu+du;
  const count=(S.cashCounts||[]).filter(x=>x.date===date).slice(-1)[0]||null;
  const actualKhr=count?+count.khr||0:null, actualUsd=count?+count.usd||0:null;
  const diffKhr=count?actualKhr-expectedKhr:null, diffUsd=count?actualUsd-expectedUsd:null;
  const cups=sales.reduce((a,x)=>a+(+x.cups||0),0);
  const itemCounts={};
  sales.forEach(s=> (s.items||[]).forEach(it=>{ itemCounts[it.id]=(itemCounts[it.id]||0)+(it.qty||0); }));
  let best="—", bestQty=0;
  Object.entries(itemCounts).forEach(([id,q])=>{ if(q>bestQty){const pr=S.products.find(p=>p.id===id);bestQty=q;best=pr?pr[S.lang]:id;} });
  return {date,sk,su,ek,eu,dk,du,csk,csu,cek,ceu,expectedKhr,expectedUsd,previousKhr,previousUsd,actualKhr,actualUsd,diffKhr,diffUsd,cups,best};
}
function cleanReportText(){
  const r=reportData(), sep=S.separator||"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━";
  const clean=v=>String(v??'').replace(/\s+/g,' ').trim();
  // Invoice-style columns: description on the left, KHR in the middle, USD on the right.
  const row=(label,khr='',usd='')=>{
    const left=clean(label).slice(0,22).padEnd(22,' ');
    const mid=clean(khr).padStart(14,' ');
    const right=clean(usd).padStart(11,' ');
    return `${left}${mid}${right}`;
  };
  const one=(label,value)=>clean(label).slice(0,22).padEnd(22,' ')+clean(value).padStart(25,' ');
  const header=`${'DESCRIPTION'.padEnd(22,' ')}${'KHR'.padStart(14,' ')}${'USD'.padStart(11,' ')}`;
  const lines=[
    `☕ ${S.cms.shopName}`,
    `${L('report')} — ${r.date}`,
    sep,
    header,
    sep,
    row(L('sales'),mKHR(r.sk),mUSD(r.su)),
    row(L('expenses'),mKHR(r.ek),mUSD(r.eu)),
    row(S.lang==='kh'?'ចំណូលសរុប':'TOTAL INCOME',mKHR(r.sk),mUSD(r.su)),
    row(S.lang==='kh'?'ចំណាយសរុប':'TOTAL EXPENSES',mKHR(r.ek),mUSD(r.eu)),
    sep,
    `🧮 ${S.lang==='kh'?'លុយក្នុងតុ':'CASH IN DRAWER'}`,
    row(L('previous'),mKHR(r.previousKhr),mUSD(r.previousUsd)),
    row(L('cashSales'),mKHR(r.csk),mUSD(r.csu)),
    row(L('cashExpenses'),mKHR(r.cek),mUSD(r.ceu)),
    row(L('deposit'),mKHR(r.dk),mUSD(r.du)),
    row(L('expected'),mKHR(r.expectedKhr),mUSD(r.expectedUsd)),
    row(L('actual'),r.actualKhr===null?'—':mKHR(r.actualKhr),r.actualUsd===null?'—':mUSD(r.actualUsd)),
    row(L('difference'),r.diffKhr===null?'—':mKHR(r.diffKhr),r.diffUsd===null?'—':mUSD(r.diffUsd)),
    sep,
    row(`🏦 ${L('deposit')}`,mKHR(r.dk),mUSD(r.du)),
    one(`☕ ${L('cups')}`,String(r.cups)),
    one(`⭐ ${L('bestSeller')}`,String(r.best)),
    one(`👤 ${L('staff')}`,String(S.user?.name||'')),
    one(`💱 ${S.lang==='kh'?'អត្រាប្តូរប្រាក់':'Exchange Rate'}`,`1 USD = ${fmt(S.settings.rate)} KHR`),
    sep,
    S.cms.footer||''
  ];
  return lines.join('\n');
}
